def thumb(src,dst):
    try:
        im=Image.open(src).convert('RGBA'); bg=Image.new('RGBA',im.size,(14,22,44,255)); im=Image.alpha_composite(bg,im).convert('RGB')
        w,h=im.size; s=min(w,h); im=im.crop(((w-s)//2,(h-s)//2,(w-s)//2+s,(h-s)//2+s)).resize((176,176),Image.LANCZOS); im.save(dst,'WEBP',quality=62); return True
    except Exception as e: print('thumb fail',src,e); return False
